  "media/creative-commons-by.svg": { text: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 -859 969 968\"><path fill=\"#000000\" transform=\"scale(1,-1)\" d=\"M615 495C615 504 612 511 606 517C600 523 592 527 584 527H385C376 527 369 523 363 517C357 511 354 504 354 495V297H409V62H560V297H615ZM417 620C417 575 439 552 484 552C529 552 552 575 552 620C552 666 529 688 484 688C439 688 417 666 417 620ZM484 859C205 859 0 635 0 375C0 104 222 -109 484 -109C738 -109 969 88 969 375C969 644 761 859 484 859ZM485 772C705 772 881 597 881 375C881 137 687 -21 485 -21C265 -21 87 161 87 375C87 581 254 772 485 772Z\"/></svg>" },
